<script setup>
import { onMounted, reactive, ref } from 'vue'
import { collectionApi } from '@/services/collection.service'
import { sheetApi } from '@/services/sheet.service'
const metadata=ref({programs:[],courses:[],academicYears:[],semesters:['1','2']}),collections=ref([]),files=ref([]),job=ref(null),error=ref(''),loading=ref(false)
const shared=reactive({programId:'',courseId:'',academicYear:'',semester:'',documentType:'Sheet'})
const destination=reactive({mode:'individual',collectionId:'',name:'',collectionType:'MIXED',courseId:''})
const mime={pdf:'application/pdf',doc:'application/msword',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',ppt:'application/vnd.ms-powerpoint',pptx:'application/vnd.openxmlformats-officedocument.presentationml.presentation',txt:'text/plain',jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png'}
function read(file,index){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>resolve({clientKey:`file-${Date.now()}-${index}`,title:file.name.replace(/\.[^.]+$/,''),fileName:file.name,fileType:file.type||mime[file.name.split('.').pop()?.toLowerCase()]||'',fileData:String(reader.result).split(',')[1]||'',courseId:'',documentType:''});reader.readAsDataURL(file)})}
async function choose(event){const selected=[...(event.target.files||[])];error.value='';if(selected.length>20||selected.some(file=>file.size>20*1024*1024)||selected.reduce((sum,file)=>sum+file.size,0)>20*1024*1024){error.value='เลือกได้ไม่เกิน 20 ไฟล์ และขนาดรวมต้องไม่เกิน 20 MB';return}try{files.value=await Promise.all(selected.map(read))}catch{error.value='อ่านไฟล์ไม่สำเร็จ'}}
function requestBody(selected=files.value){const body={sharedMetadata:{...shared},items:selected.map(file=>({...file,courseId:file.courseId||undefined,documentType:file.documentType||undefined}))};if(destination.mode==='existing')body.collectionId=destination.collectionId;if(destination.mode==='new')body.newCollection={name:destination.name,collectionType:destination.collectionType,courseId:destination.collectionType==='COURSE'?destination.courseId:null};return body}
async function submit(){loading.value=true;error.value='';try{job.value=await collectionApi.bulk(requestBody())}catch(cause){error.value=cause.message}finally{loading.value=false}}
async function retry(item){const original=files.value.find(file=>file.clientKey===item.clientKey);if(!original)return;try{job.value=await collectionApi.retry(job.value.id,{sharedMetadata:{...shared},items:[original]})}catch(cause){error.value=cause.message}}
onMounted(async()=>{try{[metadata.value,collections.value]=await Promise.all([sheetApi.metadata(),collectionApi.mine()])}catch(cause){error.value=cause.message}})
</script>
<template><form class="form" @submit.prevent="submit"><h2>อัปโหลดหลายไฟล์</h2><p>ทุกไฟล์จะเข้าสู่ขั้นตอนตรวจสอบของผู้ดูแลเหมือนการอัปโหลดปกติ</p><p v-if="error" class="form-error" role="alert">{{ error }}</p><fieldset><legend>ปลายทาง</legend><div class="button-row"><label><input v-model="destination.mode" type="radio" value="individual"> เอกสารแยก</label><label><input v-model="destination.mode" type="radio" value="existing"> Collection ที่มีอยู่</label><label><input v-model="destination.mode" type="radio" value="new"> สร้าง Collection ใหม่</label></div><label v-if="destination.mode==='existing'">Collection<select v-model="destination.collectionId" required><option value="" disabled>เลือก Collection</option><option v-for="item in collections.filter(item=>item.publicationStatus!=='ARCHIVED')" :key="item.id" :value="item.id">{{ item.name }} · {{ item.collectionType }}</option></select></label><div v-if="destination.mode==='new'" class="form-grid"><label>ชื่อ<input v-model="destination.name" maxlength="120" required></label><label>ประเภท<select v-model="destination.collectionType"><option value="MIXED">Mixed</option><option value="COURSE">Course</option></select></label><label v-if="destination.collectionType==='COURSE'">รายวิชา<select v-model="destination.courseId" required><option value="" disabled>เลือกวิชา</option><option v-for="course in metadata.courses" :key="course.id" :value="course.id">{{ course.code }} — {{ course.nameEn||course.name }}</option></select></label></div></fieldset>
<fieldset><legend>Shared metadata</legend><div class="form-grid"><label>สาขา<select v-model="shared.programId" required><option value="" disabled>เลือกสาขา</option><option v-for="program in metadata.programs" :key="program.id" :value="program.id">{{ program.nameTh||program.code }}</option></select></label><label>รายวิชา<select v-model="shared.courseId" required><option value="" disabled>เลือกวิชา</option><option v-for="course in metadata.courses" :key="course.id" :value="course.id">{{ course.code }} — {{ course.nameEn||course.name }}</option></select></label><label>ปี<select v-model="shared.academicYear" required><option v-for="year in metadata.academicYears" :key="year">{{ year }}</option></select></label><label>ภาค<select v-model="shared.semester" required><option v-for="semester in metadata.semesters" :key="semester">{{ semester }}</option></select></label><label>ประเภท<select v-model="shared.documentType"><option>Sheet</option><option>Lecture</option></select></label></div></fieldset>
<label>เลือกไฟล์ (สูงสุด 20)<input type="file" multiple required @change="choose"></label><div class="bulk-file-list"><article v-for="file in files" :key="file.clientKey" class="collection-item"><label>ชื่อ<input v-model="file.title" maxlength="200" required></label><label>Override รายวิชา<select v-model="file.courseId"><option value="">ใช้ค่าร่วม</option><option v-for="course in metadata.courses" :key="course.id" :value="course.id">{{ course.code }}</option></select></label><label>Override ประเภท<select v-model="file.documentType"><option value="">ใช้ค่าร่วม</option><option>Sheet</option><option>Lecture</option></select></label></article></div><button class="button button--primary" :disabled="loading||!files.length">{{ loading?'กำลังส่ง…':`ส่ง ${files.length} ไฟล์` }}</button>
<section v-if="job" class="bulk-result"><h3>ผล: {{ job.status }}</h3><p>สำเร็จ {{ job.succeededItems }} · ล้มเหลว {{ job.failedItems }}</p><article v-for="item in job.items" :key="item.id" class="collection-item" :data-bulk-status="item.status"><span>{{ item.clientKey }} · {{ item.status }}<small v-if="item.errorMessage"> — {{ item.errorMessage }}</small></span><button v-if="item.status==='FAILED'" type="button" class="button button--ghost button--small" @click="retry(item)">ลองใหม่</button></article></section></form></template>
